         apply (PMF.u32_at_agree RSEGS M1); [intros i Hi; apply AG; lia | lia | lia | exact H]) end
  | |- L5.u8_at ?sg ?M2 ?a ?v => match goal with H : L5.u8_at sg ?M1 ?b ?v' |- _ => tryif constr_eq M1 M2 then fail else
