Definition kont_c (R0 : bvmap 5 word) (M0 : word -> option byte) (model0 : Model) (K : TSet) (LB : list (Z * Z)) (cr : credit)
    (ois sp r : Z) (s : PM.vstr) (b : bool) (l : list Z) : Prop :=
  forall (fx' : FPState) (R' : bvmap 5 word) (M' : word -> option byte) (model' : Model) (s' : PM.vstr) (sm : PM.strm) (cr' : credit),
    regs_preserved R0 R' -> PMIS.iss_at M' ois s' sm -> PM.vs_size s' = PM.vs_size s ->
    PM.sm_g sm = PM.vs_data (ois + 80) s' -> PM.sm_st sm = 0 ->
    L5.bytes_at RSEGS M' (PM.vs_data (ois + 80) s') l ->
    PMST.loc_ok RSEGS AD M' true ->
    L5C.hpres L LB sp (PMSP.pm_scr 4) (PMIS.WF ois b) M0 M' ->
    PMSP.credit_keep cr cr' (PMIS.cost L s) PMSP.cr0 ->
    model_but_vm model0 model' -> hi_heap HI (PM.vs_own s' ++ LB) cr' M' (m_vmmaps model') ->
    srealizes RSEGS SCFG (PMSP.cfg RSEGS R' r M' model') K.

Lemma tail_short_c :
  forall (fx1 : FPState) R0 M0 model0 K LB cr ois os sp r s b R1 M1 model1 n l,
    PMIS.pre L HI R0 M0 model0 K LB cr ois os sp r s b ->
    kont_c R0 M0 model0 K LB cr ois sp r s b l ->
    Z.of_nat (length l) = PM.vs_size s -> L5.bytes_at RSEGS M0 (PM.vs_data os s) l ->
    s = PM.VShort n ->
    PMIS.mid L HI R0 M0 model0 LB cr ois os sp s b R1 M1 model1 ->
    srealizes RSEGS SCFG (@PMSP.cfg RSEGS fx1 R1 0x35404 M1 model1) K.
Proof.
